<script setup>
import { computed, ref } from 'vue';
import { Link, useForm } from '@inertiajs/vue3';
import { route } from 'ziggy-js';
import PanelLayout from '../../Components/Admin/PanelLayout.vue';
import { formatSouvenirPrice as money } from '../../Components/Catalog/souvenirCatalog';
const props = defineProps({ vendor: Object, products: Object, orders: Object, moderation: Boolean, reviews: Object });
const navigation = computed(() => props.moderation ? [{key:'souvenirs',label:'Moderasi oleh-oleh',group:'Operasional',url:route('admin.souvenirs')}] : [{key:'dashboard',label:'Dashboard vendor',group:'Bisnis',url:route('vendor.dashboard')},{key:'souvenirs',label:'Produk & pesanan oleh-oleh',group:'Operasional',url:route('vendor.souvenirs')}]);
const editing = ref(null);
const response = useForm({ vendor_response: '' });
const responses = ref({});
const trackingNumbers = ref({});
const variants = ref('Default');
const rates = ref([]);
const form = useForm({ name: '', category: 'Makanan khas', region: '', description: '', care: '', image_url: '', variants: ['Default'], price: 1000, stock: 1, weight: 100, preparation_days: 1, availability: 'Preorder', pickup_only: true, pickup_address: '', delivery_rates: [] });
const status = useForm({ status: '', tracking_number: '' });
const upload = useForm({ file: null, alt_text: '', visibility: 'public' });
function uploadPhoto() { upload.post(route('media.store'), { onSuccess: page => { const media = page.props.flash?.uploaded_media; if (media?.visibility === 'public') { form.image_url = media.url; upload.reset(); } } }); }
function edit(item) { editing.value = item; Object.keys(form.data()).forEach(key => { form[key] = item[key] ?? form[key]; }); variants.value = item.variants.join('\n'); rates.value = (item.delivery_rates || []).map(rate => ({ ...rate })); form.clearErrors(); }
function resetProduct() { editing.value = null; form.reset(); form.clearErrors(); variants.value = 'Default'; rates.value = []; }
function save() {
    form.variants = variants.value.split('\n').map(s => s.trim()).filter(Boolean);
    form.clearErrors();
    form.delivery_rates = form.pickup_only ? [] : rates.value.map(rate => ({ region: rate.region.trim(), service: rate.service.trim(), fee: Number(rate.fee) }));
    if (!form.pickup_only && !form.delivery_rates.length) { form.setError('delivery_rates', 'Tambahkan minimal satu tujuan dan tarif pengiriman.'); return; }
    if (editing.value) form.put(route('vendor.souvenirs.update', editing.value.id)); else form.post(route('vendor.souvenirs.create'));
}
function transition(order, next) { status.tracking_number = next === 'shipped' ? trackingNumbers.value[order.id] || '' : ''; status.status = next; status.put(route('vendor.souvenirs.orders.update',order.id)); }
function moderate(item, next) { status.status = next; status.put(route('admin.souvenirs.moderate',item.id)); }
</script>
<template>
    <PanelLayout :title="moderation ? 'Moderasi produk lokal' : 'Produk & pesanan oleh-oleh'" :navigation="navigation" :vendor="!moderation" subtitle="Harga vendor, stok, dan penyiapan pesanan tercatat dalam satu alur.">
        <p v-for="(error,key) in status.errors" :key="key" role="alert" class="mb-4 text-sm text-red-700">{{ error }}</p>
        <section class="panel-surface p-6"><h2 class="font-bold">Produk</h2><article v-for="item in products?.data" :key="item.id" class="mt-4 flex flex-wrap items-center justify-between gap-4 border-t border-slate-100 pt-4"><div><p class="text-sm font-bold">{{ item.name }}</p><p class="mt-2 text-xs text-slate-500">{{ item.vendor?.name || vendor?.name }} · {{ item.status }} · stok {{ item.stock }} · direservasi {{ item.reserved_stock }}</p><p class="mt-2 text-sm">Harga dasar vendor: {{ money(item.price) }}</p></div><div class="flex gap-2"><template v-if="moderation"><button class="panel-primary" :disabled="status.processing" @click="moderate(item,'published')">Terbitkan</button><button class="panel-secondary" :disabled="status.processing" @click="moderate(item,'rejected')">Tolak</button><button class="panel-secondary" :disabled="status.processing" @click="moderate(item,'archived')">Arsipkan</button></template><button v-else class="panel-secondary" @click="edit(item)">Edit</button></div></article><p v-if="!products?.data.length" class="mt-4 text-sm text-slate-500">Belum ada produk.</p><nav class="mt-5 flex gap-4" aria-label="Halaman produk"><Link v-if="products?.prev_page_url" :href="products.prev_page_url">Sebelumnya</Link><Link v-if="products?.next_page_url" :href="products.next_page_url">Berikutnya</Link></nav></section>
        <template v-if="!moderation && vendor?.status === 'verified'">
            <form class="panel-surface mt-6 p-6" @submit.prevent="save"><h2 class="font-bold">{{ editing ? 'Edit produk' : 'Tambah produk' }}</h2><p class="mt-2 text-xs text-slate-500">Perubahan produk memerlukan moderasi sebelum tampil di etalase.</p><div class="mt-5 grid gap-4 sm:grid-cols-2"><label v-for="(label,key) in {name:'Nama produk',region:'Provinsi/daerah asal',price:'Harga dasar vendor (Rp)',stock:'Stok/kuota produksi total',weight:'Berat (gram)',preparation_days:'Waktu persiapan (hari)'}" :key="key" class="text-xs font-semibold">{{ label }}<input v-model="form[key]" :type="['price','stock','weight','preparation_days'].includes(key) ? 'number' : 'text'" :required="key !== 'image_url'" class="panel-input mt-2" /></label><label class="text-xs font-semibold">Kategori<select v-model="form.category" class="panel-input mt-2"><option>Makanan khas</option><option>Kopi &amp; minuman</option><option>Kain &amp; kerajinan</option></select></label><label class="text-xs font-semibold">Ketersediaan<select v-model="form.availability" class="panel-input mt-2"><option>Preorder</option><option>Ready stock</option></select></label><label class="text-xs font-semibold">Varian, satu per baris<textarea v-model="variants" required class="panel-input mt-2"></textarea></label><label class="text-xs font-semibold sm:col-span-2">Deskripsi<textarea v-model="form.description" required class="panel-input mt-2"></textarea></label><label class="text-xs font-semibold">Perawatan/masa simpan<textarea v-model="form.care" class="panel-input mt-2"></textarea></label><label class="text-xs font-semibold">Alamat lengkap pengambilan<textarea v-model="form.pickup_address" required class="panel-input mt-2"></textarea></label><label class="flex items-center gap-2 text-sm"><input v-model="form.pickup_only" type="checkbox" />Hanya ambil di tempat</label><fieldset v-if="!form.pickup_only" class="sm:col-span-2"><legend class="text-sm font-semibold">Tujuan &amp; tarif pengiriman</legend><p class="mt-2 text-xs leading-6 text-slate-500">Tarif berlaku per unit produk. Pembeli hanya dapat memilih tujuan yang tersedia di sini.</p><div v-for="(rate,index) in rates" :key="index" class="mt-4 grid gap-3 rounded-lg border border-slate-200 p-4 sm:grid-cols-3"><label class="text-xs font-semibold">Daerah tujuan<input v-model="rate.region" required maxlength="100" class="panel-input mt-2" placeholder="DKI Jakarta" /></label><label class="text-xs font-semibold">Layanan pengiriman<input v-model="rate.service" required maxlength="100" class="panel-input mt-2" placeholder="JNE Reguler" /></label><label class="text-xs font-semibold">Ongkir per unit (Rp)<input v-model.number="rate.fee" required type="number" min="0" max="1000000" step="1" class="panel-input mt-2" /></label><button type="button" class="panel-secondary justify-self-start" :aria-label="'Hapus tujuan pengiriman ' + (index + 1)" @click="rates.splice(index,1)">Hapus tujuan</button></div><button type="button" :disabled="rates.length >= 100" class="panel-secondary mt-4" @click="rates.push({region:'',service:'',fee:0})">Tambah tujuan pengiriman</button></fieldset></div><p v-for="(error,key) in form.errors" :key="key" role="alert" class="mt-3 text-xs text-red-700">{{ error }}</p><button :disabled="form.processing" class="panel-primary mt-5">Simpan &amp; ajukan moderasi</button><button v-if="editing" type="button" class="panel-secondary ml-3" @click="resetProduct">Produk baru</button></form>
            <form class="panel-surface mt-5 p-6" @submit.prevent="uploadPhoto"><h2 class="text-sm font-bold">Foto produk</h2><p class="mt-2 text-xs text-slate-500">Foto hasil upload langsung dipasang pada produk yang sedang diisi.</p><img v-if="form.image_url" :src="form.image_url" alt="Foto produk yang dipilih" class="mt-4 h-32 w-32 rounded-lg object-cover" /><input required type="file" accept="image/jpeg,image/png,image/webp" class="mt-4" @change="upload.file = $event.target.files[0]" /><button :disabled="upload.processing" class="panel-secondary mt-4">Upload</button><p v-for="error in upload.errors" :key="error" class="mt-3 text-xs text-red-700">{{ error }}</p></form>
        </template>
        <section v-if="!moderation" class="panel-surface mt-6 p-6"><h2 class="font-bold">Pesanan</h2><article v-for="order in orders?.data" :key="order.id" class="mt-5 border-t border-slate-100 pt-5"><p class="font-bold">{{ order.reference }} · {{ order.status }}</p><p class="mt-2 text-sm">{{ order.contact_name }} · {{ order.contact_phone }} · {{ money(order.total) }}</p><p class="mt-2 whitespace-pre-line text-sm">{{ order.address }}</p><p v-if="order.pickup_date" class="mt-2 text-sm">Ambil {{ order.pickup_date.slice(0,10) }}</p><p v-for="item in order.items" :key="item.id" class="mt-2 text-xs">{{ item.name }} · {{ item.variant }} × {{ item.quantity }} · {{ item.note }}</p><div class="mt-4 flex flex-wrap gap-3"><button v-if="order.status === 'paid'" class="panel-primary" :disabled="status.processing" @click="transition(order,'processing')">Mulai persiapan</button><button v-if="order.status === 'processing' && order.method === 'pickup'" class="panel-primary" :disabled="status.processing" @click="transition(order,'ready_for_pickup')">Siap diambil</button><template v-if="order.status === 'processing' && order.method === 'delivery'"><input v-model="trackingNumbers[order.id]" aria-label="Nomor resi" placeholder="Nomor resi pengiriman" class="panel-input max-w-xs" /><button class="panel-primary" :disabled="status.processing || !trackingNumbers[order.id]" @click="transition(order,'shipped')">Kirim pesanan</button></template></div></article><nav class="mt-5 flex gap-4" aria-label="Halaman pesanan"><Link v-if="orders?.prev_page_url" :href="orders.prev_page_url">Sebelumnya</Link><Link v-if="orders?.next_page_url" :href="orders.next_page_url">Berikutnya</Link></nav></section>
<section class="panel-surface mt-6 p-6"><h2 class="font-bold">Ulasan pembeli</h2><article v-for="review in reviews?.data" :key="review.id" class="mt-4 border-t border-slate-100 pt-4"><p class="text-sm font-semibold">{{ review.product.name }} · {{ review.rating }}/5 · {{ review.status }}</p><p class="mt-3 whitespace-pre-line text-sm">{{ review.body }}</p><p v-if="review.vendor_response" class="mt-2 text-sm">Balasan toko: {{ review.vendor_response }}</p><div v-if="moderation" class="mt-3 flex gap-3"><button class="panel-primary" :disabled="status.processing" @click="status.status = 'published'; status.put(route('admin.souvenirs.reviews.moderate',review.id))">Terbitkan</button><button class="panel-secondary" :disabled="status.processing" @click="status.status = 'rejected'; status.put(route('admin.souvenirs.reviews.moderate',review.id))">Tolak</button></div><form v-else class="mt-3" @submit.prevent="response.vendor_response = responses[review.id]; response.put(route('vendor.souvenirs.reviews.reply',review.id))"><label class="text-xs font-semibold">Balasan toko<textarea v-model="responses[review.id]" minlength="5" maxlength="2000" required class="panel-input mt-2"></textarea></label><button :disabled="response.processing" class="panel-secondary mt-3">Kirim balasan untuk ditinjau</button></form></article><p v-if="!reviews?.data.length" class="mt-4 text-sm text-slate-500">Belum ada ulasan.</p><nav class="mt-5 flex gap-4" aria-label="Halaman ulasan"><Link v-if="reviews?.prev_page_url" :href="reviews.prev_page_url">Sebelumnya</Link><Link v-if="reviews?.next_page_url" :href="reviews.next_page_url">Berikutnya</Link></nav></section>
</PanelLayout>
</template>


